package com.example.lending.application.service;

import com.example.lending.application.port.in.ListLoanHistoryUseCase;
import com.example.lending.application.port.out.LoadLoanHistoryPort;
import com.example.lending.application.port.out.LoadLoanHistoryPort.LoanHistoryEntry;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.Loan;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.UUID;

@Service
@Transactional(readOnly = true)
public class ListLoanHistoryService implements ListLoanHistoryUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadLoanHistoryPort loadLoanHistoryPort;

    public ListLoanHistoryService(LoadMemberPort loadMemberPort, LoadLoanHistoryPort loadLoanHistoryPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadLoanHistoryPort = loadLoanHistoryPort;
    }

    @Override
    public List<LoanHistoryItem> listLoanHistory(UUID memberId) {
        loadMemberPort.loadMember(memberId)
                .orElseThrow(() -> new MemberNotFoundException(memberId));
        return loadLoanHistoryPort.loadLoanHistory(memberId).stream()
                .map(ListLoanHistoryService::toItem)
                .toList();
    }

    private static LoanHistoryItem toItem(LoanHistoryEntry entry) {
        Integer lateFee = entry.returnedAt() == null
                ? null
                : Loan.lateFeeBetween(entry.dueAt(), entry.returnedAt());
        return new LoanHistoryItem(entry.loanId(), entry.title(), entry.loanedAt(), entry.returnedAt(), lateFee);
    }
}
