package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberLoanHistoryIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void history_includes_returned_and_active_loans_newest_first() throws Exception {
        String memberId = registerMember("이력 회원 A");
        String oldLoanId = loanBookOn(registerBook("이력 테스트 A"), memberId, "2026-05-02");
        loanBookOn(registerBook("이력 테스트 B"), memberId, "2026-05-03");
        loanBookOn(registerBook("이력 테스트 C"), memberId, "2026-05-04");

        mockMvc.perform(post("/loans/{loanId}/return", oldLoanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-05-10\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(3))
                .andExpect(jsonPath("$[0].title").value("이력 테스트 C"))
                .andExpect(jsonPath("$[0].loanedAt").value("2026-05-04"))
                .andExpect(jsonPath("$[0].returnedAt").isEmpty())
                .andExpect(jsonPath("$[0].lateFee").isEmpty())
                .andExpect(jsonPath("$[0].loanId").isNotEmpty())
                .andExpect(jsonPath("$[1].title").value("이력 테스트 B"))
                .andExpect(jsonPath("$[1].returnedAt").isEmpty())
                .andExpect(jsonPath("$[2].title").value("이력 테스트 A"))
                .andExpect(jsonPath("$[2].loanedAt").value("2026-05-02"))
                .andExpect(jsonPath("$[2].returnedAt").value("2026-05-10"))
                .andExpect(jsonPath("$[2].lateFee").value(0));
    }

    @Test
    void returned_loan_after_due_date_shows_late_fee() throws Exception {
        String memberId = registerMember("이력 회원 B");
        String loanId = loanBookOn(registerBook("연체 이력 테스트"), memberId, "2026-06-01");

        // 대출 기한은 2026-06-15, 2026-06-20 반납이면 5일 연체 → 500원
        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-06-20\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].loanId").value(loanId))
                .andExpect(jsonPath("$[0].title").value("연체 이력 테스트"))
                .andExpect(jsonPath("$[0].returnedAt").value("2026-06-20"))
                .andExpect(jsonPath("$[0].lateFee").value(500));
    }

    @Test
    void member_without_loans_gets_empty_list() throws Exception {
        String memberId = registerMember("이력 회원 C");

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void history_of_other_members_is_not_listed() throws Exception {
        String memberId = registerMember("이력 회원 D");
        String otherMemberId = registerMember("이력 회원 E");
        loanBookOn(registerBook("다른 회원 이력 책"), otherMemberId, "2026-07-01");

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans/history", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private String loanBookOn(String bookId, String memberId, String loanedAt) throws Exception {
        String response = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(
                                Map.of("bookId", bookId, "memberId", memberId, "loanedAt", loanedAt))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("loanId").asText();
    }

    private String registerBook(String title) throws Exception {
        String response = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(response);
        return book.get("id").asText();
    }

    private String registerMember(String name) throws Exception {
        String response = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("memberId").asText();
    }
}
