import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/members/{memberId}/loans")
public class MemberLoanController {

    private final ListMemberLoansUseCase listMemberLoansUseCase;
    private final ListLoanHistoryUseCase listLoanHistoryUseCase;

    public MemberLoanController(ListMemberLoansUseCase listMemberLoansUseCase,
                                ListLoanHistoryUseCase listLoanHistoryUseCase) {
        this.listMemberLoansUseCase = listMemberLoansUseCase;
        this.listLoanHistoryUseCase = listLoanHistoryUseCase;
    }

    @GetMapping
    public ActiveLoanPageResponse listActiveLoans(@PathVariable UUID memberId,
                                                  @RequestParam(defaultValue = "0") int page,
                                                  @RequestParam(defaultValue = "20") int size) {
        ActiveLoanPage result = listMemberLoansUseCase.listActiveLoans(new ListMemberLoansQuery(memberId, page, size));
        return ActiveLoanPageResponse.from(result);
    }

    @GetMapping("/history")
    public List<LoanHistoryResponse> listLoanHistory(@PathVariable UUID memberId) {
        return listLoanHistoryUseCase.listLoanHistory(memberId).stream()
                .map(LoanHistoryResponse::from)
                .toList();
    }
}
