package com.example.lending.application.port.in;

import com.example.lending.application.port.out.LoadActiveLoansPort.ActiveLoanPage;

import java.util.UUID;

public interface ListMemberLoansUseCase {

    ActiveLoanPage listActiveLoans(ListMemberLoansQuery query);

    // page 는 0부터 시작하고, size 는 1 이상 MAX_SIZE 이하
    record ListMemberLoansQuery(UUID memberId, int page, int size) {

        public static final int MAX_SIZE = 100;

        public ListMemberLoansQuery {
            if (page < 0) {
                throw new IllegalArgumentException("page must not be negative");
            }
            if (size < 1 || size > MAX_SIZE) {
                throw new IllegalArgumentException("size must be between 1 and " + MAX_SIZE);
            }
        }
    }
}
