        // 2027-12-01 대출, 2027-12-15 기한, 2028-01-20 반납 → 36일 연체 3600원
        String loanD = loanBookOn(registerBook("통계 D"), registerMember("통계 회원 D"), "2027-12-01");
        returnBookOn(loanD, "2028-01-20");

        mockMvc.perform(get("/stats/monthly").param("year", "2028").param("month", "1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(2028))
                .andExpect(jsonPath("$.month").value(1))
                .andExpect(jsonPath("$.loanCount").value(2))
                .andExpect(jsonPath("$.returnCount").value(3))
                .andExpect(jsonPath("$.overdueCount").value(2))
                .andExpect(jsonPath("$.lateFeeTotal").value(4200));

        // 2월에는 B 의 반납만 잡힌다: 2028-01-16 기한, 2028-02-01 반납 → 16일 연체 1600원
        mockMvc.perform(get("/stats/monthly").param("year", "2028").param("month", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanCount").value(0))
                .andExpect(jsonPath("$.returnCount").value(1))
                .andExpect(jsonPath("$.overdueCount").value(1))
                .andExpect(jsonPath("$.lateFeeTotal").value(1600));
    }

    @Test
    void month_without_activity_returns_zeros() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2028").param("month", "6"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(2028))
                .andExpect(jsonPath("$.month").value(6))
                .andExpect(jsonPath("$.loanCount").value(0))
                .andExpect(jsonPath("$.returnCount").value(0))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));
    }

    @Test
    void invalid_month_returns_400() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2028").param("month", "13"))
                .andExpect(status().isBadRequest());

        mockMvc.perform(get("/stats/monthly").param("year", "2028").param("month", "0"))
                .andExpect(status().isBadRequest());
    }

    private void returnBookOn(String loanId, String returnedAt) throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"" + returnedAt + "\"}"))
                .andExpect(status().isOk());
    }

    private String loanBookOn(String bookId, String memberId, String loanedAt) throws Exception {
        String response = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(
                                Map.of("bookId", bookId, "memberId", memberId, "loanedAt", loanedAt))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("loanId").asText();
    }

    private String registerBook(String title) throws Exception {
        String response = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(response);
        return book.get("id").asText();
    }

    private String registerMember(String name) throws Exception {
        String response = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("memberId").asText();
    }
